mapper.select:
SELECT c.*, a.code AS account_code, a.name AS account_name, CASE WHEN EXISTS (SELECT 1 FROM fin_io_doc_item i WHERE i.category_id = c.id) THEN 1 ELSE 0 END AS used FROM fin_io_category c LEFT JOIN fin_account a ON a.id = c.account_id
AND c.direction = #{direction} AND c.status = #{status}
ORDER BY c.direction, c.sort, c.id
